const items = $input.all();
const dataset = items[0].json.body.data || items[0].json.body.dataset || [];

if (!Array.isArray(dataset) || dataset.length === 0) {
  return [{ json: { error: 'No dataset provided', scores: {} } }];
}

const columns = Object.keys(dataset[0]);
const totalRows = dataset.length;

// Completeness: % of non-null/empty values
const completeness = {};
for (const col of columns) {
  const filled = dataset.filter(row => row[col] !== null && row[col] !== undefined && row[col] !== '').length;
  completeness[col] = parseFloat((filled / totalRows * 100).toFixed(1));
}
const avgCompleteness = parseFloat((Object.values(completeness).reduce((a, b) => a + b, 0) / columns.length).toFixed(1));

// Consistency: check for mixed types per column
const consistency = {};
for (const col of columns) {
  const types = new Set(dataset.map(row => typeof row[col]));
  consistency[col] = types.size === 1 ? 100 : parseFloat((100 - (types.size - 1) * 25).toFixed(1));
}
const avgConsistency = parseFloat((Object.values(consistency).reduce((a, b) => a + b, 0) / columns.length).toFixed(1));

// Uniqueness: % of unique values per column
const uniqueness = {};
for (const col of columns) {
  const values = dataset.map(row => row[col]);
  const unique = new Set(values).size;
  uniqueness[col] = parseFloat((unique / totalRows * 100).toFixed(1));
}

// Duplicates: full-row duplicates
const rowStrings = dataset.map(row => JSON.stringify(row));
const uniqueRows = new Set(rowStrings).size;
const duplicateRate = parseFloat(((1 - uniqueRows / totalRows) * 100).toFixed(1));

const overallScore = parseFloat(((avgCompleteness + avgConsistency + (100 - duplicateRate)) / 3).toFixed(1));

return [{
  json: {
    totalRows,
    totalColumns: columns.length,
    overallScore,
    completeness: { average: avgCompleteness, byColumn: completeness },
    consistency: { average: avgConsistency, byColumn: consistency },
    uniqueness: { byColumn: uniqueness },
    duplicateRate,
    duplicateRows: totalRows - uniqueRows,
    columnNames: columns
  }
}];
